            <section class="panel"><div class="section-heading"><div><h2>Mục tiêu & lịch tuần tới</h2><p class="muted">Ngày giờ dự kiến không làm thay đổi điểm streak.</p></div><span>📅</span></div><form method="post" class="stack-form"><input type="hidden" name="_csrf" value="<?= sf_h(sf_csrf_token()) ?>"><input type="hidden" name="action" value="save_goal"><input type="hidden" name="week_start" value="<?= sf_h($nextWeek) ?>"><label>Số buổi đăng ký tuần tới<select name="target_sessions"><?php for ($i = 1; $i <= 7; $i++): ?><option value="<?= $i ?>" <?= (int)$nextGoal['target_sessions'] === $i ? 'selected' : '' ?>><?= $i ?> buổi / tuần</option><?php endfor; ?></select></label><div class="schedule-grid"><?php foreach ($nextDates as $date): $dateKey = $date->format('Y-m-d'); ?><label><?= sf_h($date->format('D · d/m')) ?><input type="hidden" name="planned_dates[]" value="<?= sf_h($dateKey) ?>"><input type="time" name="planned_times[]" value="<?= sf_h($nextPlanByDate[$dateKey]['planned_time'] ?? '') ?>"></label><?php endforeach; ?></div><button class="btn secondary full">Lưu mục tiêu và lịch dự kiến</button></form></section>
