ề xuất<input name="amount" type="number" min="1000" max="1000000" step="1000" required placeholder="Ví dụ: 50.000"></label><button class="btn secondary">Lưu đề xuất</button></form><?php endif; ?><?php if ($fund['status'] === 'voting' && $fundMember && (int)$fundMember['opted_in'] && $fundProposals): ?><form method="post" class="fund-inline-form"><input type="hidden" name="_csrf" value="<?= sf_h(sf_csrf_token()) ?>"><input type="hidden" name="action" value="fund_vote"><label>Bỏ phiếu<select name="amount"><?php $seenAmounts = []; foreach ($fundProposals as $proposal): if (isset($seenAmounts[$proposal['amount']])) continue; $seenAmounts[$proposal['amount']] = true; ?><option value="<?= (int)$proposal['amount'] ?>"><?= number_format((int)$proposal['amount']) ?>đ</option><?php endforeach; ?></select></label><button class="btn secondary">Gửi phiếu</button></form><?php endif; ?><?php if ($fundVotes): ?><div class="fund-votes"><?php foreach ($fundVotes as $vote): ?><span><?= number_format((int)$vote['amount']) ?>đ · <?= (int)$vote['votes'] ?> phiếu</span><?php endforeach; ?></div><?php endif; ?></div><?php if ($fund['status'] === 'closed'): ?><div class="final-penalty">Mức phạt tháng đã chốt: <b><?= number_format((int)$fund['final_penalty']) ?>đ</b></div><?php endif; ?><?php if ($isAdmin): ?><div class="admin-fund-controls"><?php foreach ($fundMembers as $member): ?><?php if ($member['contribution_status'] === 'unpaid'): ?><form method="post" class="fund-member-row"><span><?= sf_h($member['display_name']) ?></span><input type="hidden" name="_csrf" value="<?= sf_h(sf_csrf_token()) ?>"><input type="hidden" name="action" value="fund_mark_paid"><input type="hidden" name="member_id" value="<?= (int)$member['user_id'] ?>"><button class="text-link">Đánh dấu đã đóng</button></form><?php endif; ?><?php endforeach; ?><?php if ($fund['status'] === 'open' && $fundProposals): ?><form method="post"><input type="hidden" name="_csrf" value="<?= sf_h(sf_csrf_token()) ?>"><input type="hidden" name="action" value="fund_start_vote"><button class="btn secondary full">Mở biểu quyết mức phạt</button></form><?php elseif ($fund['status'] === 'voting'): ?><form method="post"><input type="hidden" name="_csrf" value="<?= sf_h(sf_csrf_token()) ?>"><input type="hidden" name="action" value="fund_close_vote"><button class="btn secondary full">Chốt mức phạt theo phiếu</button></form><?php endif; ?></div><?php endif; ?></section>
            <section class="panel assistant-panel"><div class="section-heading"><div><h2>Trợ lý sức khỏe ✨</h2><p class="muted">Câu trả lời mẫu, không thay thế tư vấn y tế.</p></div></div><div class="assistant-answer" id="assistantAnswer">Chào <?= sf_h(explode(' ', trim($user['display_name']))[0]) ?>! Hãy tập vừa sức, ngủ đủ và ghi nhận tiến bộ theo tuần.</div><form class="assistant-form" id="assistantForm"><input id="assistantQuestion" maxlength="160" placeholder="Hỏi về BMI, mục tiêu tập…"><button class="btn primary">Gửi</button></form></section>
        <?php endif; ?>
    </main>
    <nav class="bottom-nav" aria-label="Điều hướng chính"><?php foreach ($tabLabels as $key => $label): ?><a class="nav-item <?= $tab === $key ? 'active' : '' ?> <?= $key === 'checkin' ? 'nav-checkin' : '' ?>" href="?tab=<?= sf_h($key) ?>"><span><?= ['feed' => '⌂', 'leaderboard' => '♛', 'checkin' => '＋', 'notifications' => '♧', 'profile' => '◉'][$key] ?></span><small><?= sf_h($label) ?></small><?php if ($key === 'notifications' && $unreadCount): ?><i class="nav-dot"></i><?php endif; ?></a><?php endforeach; ?></nav>
</div>
